put('frontend/src/features/profile-hosts/host-routing.test.ts','''import {expect,it} from 'vitest'
import {personalHostTarget,personalHostApiAllowed,publicHostCookies,personalHostOrigin} from './host-routing'
const bases=JSON.stringify({'temlinkaqui.com':'temlinkaqui.com'})
it('F10-U01 hostname exato não confia em X-Forwarded-Host ou sufixo parecido',()=>{expect(personalHostTarget('ANA.temlinkaqui.com:443',bases)).toEqual({hostname:'ana.temlinkaqui.com',tenantHost:'temlinkaqui.com'});for(const host of ['temlinkaqui.com','ana.temlinkaqui.com.evil.test','eviltemlinkaqui.com','ana@temlinkaqui.com'])expect(personalHostTarget(host,bases)).toBeNull();expect(personalHostOrigin('temlinkaqui.com','3000')).toBe('https://temlinkaqui.com')})
it('F10-C02 BFF permite somente APIs públicas da mesma página e métodos previstos',()=>{for(const path of ['/v1/profiles/ana','/v1/profiles/ana/items','/v1/profiles/ana/avatar/'+'a'.repeat(64)])expect(personalHostApiAllowed('GET',path,'ana')).toBe(true);for(const [method,path] of [['GET','/v1/me/profile'],['POST','/v1/auth/refresh'],['GET','/v1/profiles/bia'],['POST','/v1/profiles/ana/publish'],['DELETE','/v1/profiles/ana/contact-form'],['GET','/v1/admin/config']])expect(personalHostApiAllowed(method,path,'ana')).toBe(false);expect(personalHostApiAllowed('POST','/v1/profiles/ana/contact-form/submissions','ana')).toBe(true)})
it('F10-I01 cookies privados não atravessam BFF público; consentimento permanece independente',()=>{expect(publicHostCookies('accessToken=secret; refreshToken=secret; catalogo_role=ADMIN; workspaceOwner=other; age=yes; tla_consent=denied; tla_profile_measure=v1_yes; analyticsSession=public')).toBe('age=yes; tla_consent=denied; tla_profile_measure=v1_yes; analyticsSession=public')})
''')
p=r/'frontend/src/middleware.test.ts';s=p.read_text(encoding='utf-8');s+='''
it('F10-I01 host pessoal reescreve só a página mapeada e elimina contexto forjado',async()=>{vi.stubEnv('PROFILE_HOST_BASES','{"pages.test":"tenant.test"}');vi.stubGlobal('fetch',vi.fn().mockResolvedValue(Response.json({mode:'PAGE',slug:'ana',tenantHost:'tenant.test'})));const response=await middleware(new NextRequest('https://ana.pages.test/',{headers:{host:'ana.pages.test','x-profile-tenant-host':'evil.test','x-profile-hostname':'evil.test'}}));expect(response.headers.get('x-middleware-rewrite')).toBe('https://ana.pages.test/p/ana');expect(response.headers.get('x-middleware-request-x-profile-tenant-host')).toBe('tenant.test');expect(response.headers.get('x-middleware-request-x-profile-hostname')).toBe('ana.pages.test');expect(response.headers.get('set-cookie')).not.toMatch(/accessToken|refreshToken|Domain=/i);expect((await middleware(new NextRequest('https://ana.pages.test/p/bia',{headers:{host:'ana.pages.test'}}))).status).toBe(404);expect((await middleware(new NextRequest('https://ana.pages.test/login',{headers:{host:'ana.pages.test'}}))).status).toBe(404)})
it('F10-T06 host sem cobertura redireciona para básico sem destino arbitrário',async()=>{vi.stubEnv('PROFILE_HOST_BASES','{"pages.test":"tenant.test"}');vi.stubGlobal('fetch',vi.fn().mockResolvedValue(Response.json({mode:'FALLBACK',slug:'ana',tenantHost:'tenant.test'})));const response=await middleware(new NextRequest('https://ana.pages.test/',{headers:{host:'ana.pages.test'}}));expect(response.status).toBe(307);expect(response.headers.get('location')).toBe('https://tenant.test/p/ana')})
it('F10-I02 host desconhecido fecha em 404; falha externa não cai no catálogo',async()=>{vi.stubEnv('PROFILE_HOST_BASES','{"pages.test":"tenant.test"}');vi.stubGlobal('fetch',vi.fn().mockResolvedValue(new Response(null,{status:404})));expect((await middleware(new NextRequest('https://unknown.pages.test/',{headers:{host:'unknown.pages.test'}}))).status).toBe(404);vi.stubGlobal('fetch',vi.fn().mockRejectedValue(new Error('offline')));expect((await middleware(new NextRequest('https://unknown.pages.test/',{headers:{host:'unknown.pages.test'}}))).status).toBe(503)})
''';p.write_text(s,encoding='utf-8')
put('frontend/src/features/profile-hosts/profile-host-screen.test.tsx','''import '@testing-library/jest-dom/vitest'
import {render,screen,within,cleanup,waitFor} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import {afterEach,expect,it,vi} from 'vitest'
import {ProfileHostScreen} from './profile-host-screen'
const request=vi.hoisted(()=>vi.fn());vi.mock('@/features/profiles/profile-api',()=>({profileRequest:request}))
afterEach(()=>{cleanup();request.mockReset()})
const state={hosts:[],version:0,bases:['pages.test'],allowed:true,published:true,hasPage:true}
it('F10-C01 reserva explícita e falha recuperável conservam endereço digitado',async()=>{const user=userEvent.setup();request.mockImplementation(async(_path:string,init?:RequestInit)=>{if(init)throw new Error('DNS indisponível');return state});render(<ProfileHostScreen/>);await waitFor(()=>expect(screen.getByRole('button',{name:'Escolher endereço'})).toBeEnabled());await user.click(screen.getByRole('button',{name:'Escolher endereço'}));const dialog=screen.getByRole('dialog',{name:'Escolher endereço'});await user.type(within(dialog).getByLabelText('Nome do seu endereço'),'ana');await user.click(within(dialog).getByRole('button',{name:'Reservar endereço'}));expect(await within(dialog).findByRole('alert')).toHaveTextContent('DNS indisponível');expect(within(dialog).getByLabelText('Nome do seu endereço')).toHaveValue('ana');expect(request).toHaveBeenLastCalledWith('/hosts',{method:'POST',body:JSON.stringify({name:'ana',base:'pages.test',expectedVersion:0})})})
it('F10-C02 sem capacidade bloqueia edição; prévia reutiliza rota existente',async()=>{request.mockResolvedValue({...state,allowed:false});render(<ProfileHostScreen/>);await screen.findByText('Plano com endereço próprio necessário');expect(screen.getByRole('button',{name:'Escolher endereço'})).toBeDisabled();expect(screen.getByRole('link',{name:'Ver prévia da página'})).toHaveAttribute('href','/painel/perfil/previa');expect(screen.queryByRole('dialog')).not.toBeInTheDocument()})
it('F10-C01 carregamento usa composição igual e não chama transporte do skeleton de rota',()=>{render(<ProfileHostScreen pendingOnly/>);expect(screen.getByRole('article',{name:'Seu endereço'})).toHaveAttribute('aria-busy','true');expect(screen.getByRole('button',{name:'Escolher endereço'})).toBeDisabled();expect(request).not.toHaveBeenCalled()})
''')
put('frontend/src/features/profile-hosts/host-bff.test.ts','''import {afterEach,expect,it,vi} from 'vitest'
import {GET} from '@/app/bff/[...path]/route'
const mocks=vi.hoisted(()=>({forward:vi.fn(),resolve:vi.fn()}));vi.mock('@/lib/upstream',()=>({tenantHost:(v:string)=>v,forward:mocks.forward}));vi.mock('./server/resolve-host',()=>({resolvePersonalHost:mocks.resolve}));afterEach(()=>{vi.unstubAllEnvs();vi.clearAllMocks()})
it('F10-I01 BFF descarta autenticação/contexto e Set-Cookie privado no host público',async()=>{vi.stubEnv('PROFILE_HOST_BASES','{"pages.test":"tenant.test"}');mocks.resolve.mockResolvedValue({mode:'PAGE',slug:'ana',tenantHost:'tenant.test'});mocks.forward.mockResolvedValue({status:200,headers:{'content-type':'application/json','set-cookie':['accessToken=secret; Path=/','age=yes; Path=/','csrf=public; Domain=pages.test']},body:Buffer.from('{}')});const response=await GET(new Request('https://ana.pages.test/bff/v1/profiles/ana/items',{headers:{host:'ana.pages.test',cookie:'accessToken=secret; refreshToken=secret; age=yes; catalogo_role=ADMIN; workspaceOwner=other',authorization:'Bearer secret','x-workspace-owner':'other','x-profile-id':'private'}}),{params:Promise.resolve({path:['v1','profiles','ana','items']})});expect(response.status).toBe(200);expect(mocks.forward.mock.calls[0][0]).toMatchObject({host:'tenant.test',authorization:'',profileTarget:'',workspaceTarget:'',cookie:'age=yes'});expect(response.headers.get('set-cookie')).toBe('age=yes; Path=/')})
it('F10-I02 BFF nega outra página e operações privadas antes de transportar',async()=>{vi.stubEnv('PROFILE_HOST_BASES','{"pages.test":"tenant.test"}');mocks.resolve.mockResolvedValue({mode:'PAGE',slug:'ana',tenantHost:'tenant.test'});for(const path of [['v1','me','profile'],['v1','profiles','bia']])expect((await GET(new Request('https://ana.pages.test/bff/'+path.join('/'),{headers:{host:'ana.pages.test'}}),{params:Promise.resolve({path})})).status).toBe(404);expect(mocks.forward).not.toHaveBeenCalled()})
''')
